
CREATE TABLE app_users (id VARCHAR(36) PRIMARY KEY, email VARCHAR(254) NOT NULL UNIQUE, password_hash VARCHAR(100), name VARCHAR(120) NOT NULL, role VARCHAR(20) NOT NULL DEFAULT 'STUDENT', banned BOOLEAN NOT NULL DEFAULT FALSE, token_version INT NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE profiles (user_id VARCHAR(36) PRIMARY KEY REFERENCES app_users(id), college VARCHAR(200) DEFAULT '', course VARCHAR(100) DEFAULT '', branch VARCHAR(100) DEFAULT '', study_year VARCHAR(20) DEFAULT '', graduation_year VARCHAR(10) DEFAULT '', career_goal VARCHAR(200) DEFAULT '', skills TEXT DEFAULT '', projects TEXT DEFAULT '', photo_url TEXT DEFAULT '', public_profile BOOLEAN NOT NULL DEFAULT FALSE, reputation INT NOT NULL DEFAULT 0);
CREATE TABLE password_resets (token_hash VARCHAR(64) PRIMARY KEY, user_id VARCHAR(36) NOT NULL REFERENCES app_users(id), expires_at TIMESTAMP NOT NULL);
CREATE TABLE resumes (id VARCHAR(36) PRIMARY KEY, user_id VARCHAR(36) NOT NULL REFERENCES app_users(id), name VARCHAR(250) NOT NULL, content TEXT NOT NULL, document_json TEXT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_resume_user ON resumes(user_id, created_at);
CREATE TABLE resume_analyses (id VARCHAR(36) PRIMARY KEY, resume_id VARCHAR(36) NOT NULL REFERENCES resumes(id) ON DELETE CASCADE, result_json TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE resume_versions (id VARCHAR(36) PRIMARY KEY, resume_id VARCHAR(36) NOT NULL REFERENCES resumes(id) ON DELETE CASCADE, original_text TEXT NOT NULL, tailored_text TEXT NOT NULL, changes_json TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE resume_templates (id VARCHAR(40) PRIMARY KEY, name VARCHAR(80) NOT NULL);
INSERT INTO resume_templates VALUES ('minimal','ATS Minimal'),('developer','Software Developer'),('fresher','Fresher'),('modern','Modern'),('academic','Academic'),('data','Data / AI');
CREATE TABLE job_descriptions (id VARCHAR(36) PRIMARY KEY, user_id VARCHAR(36) NOT NULL REFERENCES app_users(id), content TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE job_matches (id VARCHAR(36) PRIMARY KEY, job_id VARCHAR(36) NOT NULL REFERENCES job_descriptions(id), resume_id VARCHAR(36) NOT NULL REFERENCES resumes(id), result_json TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE interviews (id VARCHAR(36) PRIMARY KEY, user_id VARCHAR(36) NOT NULL REFERENCES app_users(id), role VARCHAR(100) NOT NULL, kind VARCHAR(30) NOT NULL, difficulty VARCHAR(20) NOT NULL, duration INT NOT NULL, scheduled_at TIMESTAMP, started_at TIMESTAMP, status VARCHAR(20) NOT NULL DEFAULT 'SCHEDULED', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_interview_user ON interviews(user_id, scheduled_at);
CREATE TABLE interview_questions (id VARCHAR(36) PRIMARY KEY, interview_id VARCHAR(36) NOT NULL REFERENCES interviews(id) ON DELETE CASCADE, position INT NOT NULL, content TEXT NOT NULL, UNIQUE(interview_id, position));
CREATE TABLE interview_answers (id VARCHAR(36) PRIMARY KEY, question_id VARCHAR(36) NOT NULL UNIQUE REFERENCES interview_questions(id) ON DELETE CASCADE, content TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE interview_reports (id VARCHAR(36) PRIMARY KEY, interview_id VARCHAR(36) NOT NULL UNIQUE REFERENCES interviews(id) ON DELETE CASCADE, result_json TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE categories (name VARCHAR(60) PRIMARY KEY);
INSERT INTO categories VALUES ('Programming'),('DSA'),('DBMS'),('OS'),('Computer Networks'),('Web Development'),('AI/ML'),('Mathematics'),('Engineering'),('Resume'),('Interview'),('Career'),('General');
CREATE TABLE questions (id VARCHAR(36) PRIMARY KEY, user_id VARCHAR(36) NOT NULL REFERENCES app_users(id), title VARCHAR(250) NOT NULL, original_title VARCHAR(250) NOT NULL, body TEXT NOT NULL, category VARCHAR(60) NOT NULL REFERENCES categories(name), ai_explanation TEXT, embedding TEXT, embedding_model VARCHAR(150), hidden BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_question_category ON questions(category, created_at);
CREATE TABLE answers (id VARCHAR(36) PRIMARY KEY, question_id VARCHAR(36) NOT NULL REFERENCES questions(id) ON DELETE CASCADE, user_id VARCHAR(36) NOT NULL REFERENCES app_users(id), body TEXT NOT NULL, verified_by VARCHAR(36) REFERENCES app_users(id), accepted BOOLEAN NOT NULL DEFAULT FALSE, hidden BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_answer_question ON answers(question_id, created_at);
CREATE TABLE comments (id VARCHAR(36) PRIMARY KEY, question_id VARCHAR(36) NOT NULL REFERENCES questions(id) ON DELETE CASCADE, user_id VARCHAR(36) NOT NULL REFERENCES app_users(id), body VARCHAR(2000) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE votes (user_id VARCHAR(36) NOT NULL REFERENCES app_users(id), answer_id VARCHAR(36) NOT NULL REFERENCES answers(id) ON DELETE CASCADE, value INT NOT NULL CHECK (value IN (-1,1)), PRIMARY KEY(user_id, answer_id));
CREATE TABLE bookmarks (user_id VARCHAR(36) NOT NULL REFERENCES app_users(id), question_id VARCHAR(36) NOT NULL REFERENCES questions(id) ON DELETE CASCADE, PRIMARY KEY(user_id,question_id));
CREATE TABLE reports (id VARCHAR(36) PRIMARY KEY, user_id VARCHAR(36) NOT NULL REFERENCES app_users(id), target_id VARCHAR(36) NOT NULL, target_type VARCHAR(20) NOT NULL, reason VARCHAR(1000) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'OPEN', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_id,target_id,target_type));
CREATE TABLE badges (id VARCHAR(40) PRIMARY KEY, name VARCHAR(100) NOT NULL, description VARCHAR(200) NOT NULL);
INSERT INTO badges VALUES ('helper','Coding Helper','Earn 50 reputation'),('solver','Problem Solver','Have an answer marked helpful'),('faculty','Faculty Verified Contributor','Receive faculty verification'),('expert','Academic Expert','Earn 200 reputation'),('mentor','Resume Mentor','Have a helpful resume answer'),('top','Top Contributor','Earn 500 reputation');
CREATE TABLE user_badges (user_id VARCHAR(36) NOT NULL REFERENCES app_users(id), badge_id VARCHAR(40) NOT NULL REFERENCES badges(id), earned_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(user_id,badge_id));
CREATE TABLE career_goals (id VARCHAR(36) PRIMARY KEY, user_id VARCHAR(36) NOT NULL REFERENCES app_users(id), title VARCHAR(200) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE career_roadmaps (id VARCHAR(36) PRIMARY KEY, user_id VARCHAR(36) NOT NULL REFERENCES app_users(id), goal_id VARCHAR(36) NOT NULL REFERENCES career_goals(id), summary TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE roadmap_items (id VARCHAR(36) PRIMARY KEY, roadmap_id VARCHAR(36) NOT NULL REFERENCES career_roadmaps(id) ON DELETE CASCADE, title VARCHAR(200) NOT NULL, position INT NOT NULL, progress INT NOT NULL DEFAULT 0 CHECK (progress BETWEEN 0 AND 100), learn TEXT NOT NULL, practice TEXT NOT NULL, build TEXT NOT NULL, interview TEXT NOT NULL);
CREATE TABLE notifications (id VARCHAR(36) PRIMARY KEY, user_id VARCHAR(36) NOT NULL REFERENCES app_users(id), kind VARCHAR(40) NOT NULL, message VARCHAR(500) NOT NULL, link VARCHAR(200) NOT NULL, read_at TIMESTAMP, event_key VARCHAR(100) UNIQUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_notification_user ON notifications(user_id, created_at);
CREATE TABLE ai_usage (id VARCHAR(36) PRIMARY KEY, user_id VARCHAR(36) NOT NULL REFERENCES app_users(id), task VARCHAR(40) NOT NULL, success BOOLEAN NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_ai_user ON ai_usage(user_id,created_at);
CREATE TABLE rate_limits (bucket_key VARCHAR(250) PRIMARY KEY, count INT NOT NULL, window_start BIGINT NOT NULL);
